// Lafla — extra C1/C2 vocabulary for "Today's 10 Words".
//
// The daily-words pool is mostly built from vocab_tile exercises in the lesson
// packs, which are thin at the top of the scale (C1 ~360, C2 ~90 unique words).
// This curated list tops those bands up with academic / IELTS / work / opinion
// vocabulary, phrasal verbs and collocations that adult Turkish learners
// actually need. lib/daily-words.ts merges it into the pool; lesson words win
// on a duplicate key, and a test keeps this list free of lesson duplicates.
//
// Row format: [word, Turkish translation, example, example in Turkish].
// Rules: ≤4 words, lowercase Turkish unless a proper noun, no duplicates.

export interface ExtraDailyWord {
  word: string;
  translation: string;
  cefr: "C1" | "C2";
  example: string;
  exampleTr: string;
}

type Row = readonly [word: string, translation: string, example: string, exampleTr: string];

