function expand(rows: ReadonlyArray<Row>, cefr: "C1" | "C2"): ExtraDailyWord[] {
  return rows.map(([word, translation, example, exampleTr]) => ({
    word,
    translation,
    cefr,
    example,
    exampleTr,
  }));
}

export const DAILY_WORDS_EXTRA: ReadonlyArray<ExtraDailyWord> = [
  ...expand(C1, "C1"),
  ...expand(C2, "C2"),
];
